DATA = json.loads(zlib.decompress(base64.b85decode(FIXTURE)))


def reports():
    # SARIF was produced by the retained, hash-verified native Trivy 0.70.0
    # converter, independently of the implementation under test.
    return tuple(copy.deepcopy(DATA[k]) for k in ('synthetic_fs', 'actual_config', 'synthetic_sarif'))


def findings(report):
    return [(r, f) for r in report['Results'] for f in r.get('Misconfigurations', [])]


def env_fixture(root, temp):
    event = temp / 'event.json'
    event.write_text(c.canonical(dict(repository=dict(full_name=c.REPOSITORY),
        pull_request=dict(base=dict(repo=dict(full_name=c.REPOSITORY)), head=dict(sha='a'*40)))))
    return dict(PATH=os.environ['PATH'], HOME=str(temp), GITHUB_WORKSPACE=str(root), RUNNER_TEMP=str(temp),
        GITHUB_EVENT_PATH=str(event), GITHUB_OUTPUT=str(temp/'output'), GITHUB_EVENT_NAME='pull_request',
        GITHUB_REPOSITORY=c.REPOSITORY, CC_REPOSITORY=c.REPOSITORY, CC_HEAD_SHA='a'*40,
        CC_WORKFLOW_REF=c.WORKFLOW_REF, CC_WORKFLOW_SHA='b'*40,
        GITHUB_WORKFLOW_REF=c.WORKFLOW_REF, GITHUB_WORKFLOW_SHA='b'*40, GITHUB_RUN_ID='123', GITHUB_RUN_ATTEMPT='1')


def rejected_repository_urls():
    origin = 'https://github.com/' + c.REPOSITORY
    variants = [
        'https://github.com/foreign/repo', origin + '-foreign', origin + '.git.git',
        origin + '/', origin + '.git/', origin + '/extra', origin + '?x=1',
        origin + '.git?x=1', origin + '#main', origin + '.git#main',
        origin.replace('https:', 'http:'), origin.replace('https:', 'git:'),
        origin.replace('https:', 'ssh:'), 'git@github.com:' + c.REPOSITORY + '.git',
        origin.replace('github.com', 'github.com.evil.invalid'),
        origin.replace('github.com', 'github.com:443'),
        origin.replace('github.com', 'user@github.com'),
        origin.replace('github.com', 'user:password@github.com'),
        origin.replace('github.com', 'github.com@evil.invalid'),
        origin.replace('github.com', 'GITHUB.COM'), origin.lower(),
        origin.replace('/CyberCoach-NC', '/other/../CyberCoach-NC'),
        origin.replace('/CyberCoach-NC', '//CyberCoach-NC'),
        origin.replace('CyberCoach', '%43yberCoach'), origin + '%2Egit',
        origin.replace('https://', 'https:\\'), '',
    ]
    for suffix in ('', '.git'):
        for space in (' ', '\t', '\r', '\n', '\v', '\f', '\u00a0'):
            variants.extend((space + origin + suffix, origin + suffix + space))
    return variants


class Contract(unittest.TestCase):
    def test_real_config_and_full_category_fixture(self):
        fs, config, sarif = reports()
        original = c.canonical([fs, config, sarif])
        receipt = c.classify(fs, config, sarif)
        self.assertEqual(c.canonical([fs, config, sarif]), original)
        self.assertEqual(len(receipt['accepted_high_findings']), 2)
        self.assertEqual(len(receipt['iac_findings']), 7)
        self.assertEqual(receipt['finding_counts_by_kind_and_severity']['Licenses/UNKNOWN'], 3)
        self.assertEqual(receipt['unaccepted_high_critical_findings'], [])

    def test_current_fixture_records_actual_scan_coverage(self):
        # Current full scan uses the same four production scanners and one pinned DB.
        self.assertEqual(DATA['actual_scan_coverage']['scanners'], ['vuln', 'misconfig', 'secret', 'license'])
        self.assertTrue(DATA['actual_scan_coverage']['vulnerability_scan_performed'])
        argv = c.commands('/trusted/trivy', Path('/source'), Path('/out'), Path('/cache'))[0]
        self.assertEqual(argv[argv.index('--scanners') + 1], 'vuln,misconfig,secret,license')
        self.assertNotIn('--skip-db-update', argv)

