class Source(unittest.TestCase):
    def setUp(self):
        self.temp=tempfile.TemporaryDirectory();self.addCleanup(self.temp.cleanup)
        self.root=Path(self.temp.name).resolve()/'source';self.root.mkdir()
        self.env=dict(os.environ)
        self.git('init','-q');self.git('config','user.name','synthetic');self.git('config','user.email','synthetic@example.invalid')
        self.git('remote','add','origin','https://github.com/'+c.REPOSITORY+'.git')
        for name,body in DATA['source'].items():
            path=self.root/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(body)
        self.git('add','.');self.git('commit','-qm','reviewed source')
        self.head=self.git('rev-parse','HEAD')
    def git(self,*args):
        return subprocess.check_output(['git','-C',str(self.root),*args],stderr=subprocess.DEVNULL,text=True).strip()
    def test_clean_actual_head_tree_and_unrelated_commit(self):
        before=c.source(self.root,self.head,self.env)
        (self.root/'unrelated.txt').write_text('an unrelated source fix')
        self.git('add','.');self.git('commit','-qm','unrelated change')
        head=self.git('rev-parse','HEAD')
        after=c.source(self.root,head,self.env)
        self.assertNotEqual(before['commit'],after['commit'])
        self.assertNotEqual(before['tree'],after['tree'])
        self.assertEqual(before['source_sha256'],after['source_sha256'])
        with self.assertRaises(ValueError):c.source(self.root,self.head,self.env)
    def test_each_relevant_source_change_committed_still_rejected(self):
        for name in c.SOURCES:
            with self.subTest(name=name):
                path=self.root/name;body=path.read_text();path.write_text(body+'\n# changed\n')
                self.git('add','.');self.git('commit','-qm','changed policy source')
                with self.assertRaisesRegex(ValueError,'reviewed-source-hash'):
                    c.source(self.root,self.git('rev-parse','HEAD'),self.env)
                path.write_text(body);self.git('add','.');self.git('commit','-qm','restore')
    def test_sse_kms_or_recursive_logging_source_rejected(self):
        path=self.root/'infra/aws/operator-foundations/access-logging.tf'
        original=path.read_text()
        changes=[original.replace('"AES256"','"aws:kms"'),
                 original+'\nresource "aws_s3_bucket_logging" "recursive" {\n'
                 '  bucket = aws_s3_bucket.access_logs.id\n'
                 '  target_bucket = aws_s3_bucket.access_logs.id\n'
                 '  target_prefix = "recursive/"\n}\n']
        for changed in changes:
            body=path.read_text();self.assertNotEqual(body,changed)
            path.write_text(changed);self.git('add','.');self.git('commit','-qm','changed receiver')
            with self.assertRaises(ValueError):c.source(self.root,self.git('rev-parse','HEAD'),self.env)
            path.write_text(body);self.git('add','.');self.git('commit','-qm','restore')
    def test_dirty_untracked_ignored_and_source_link(self):
        path=self.root/'new.txt';path.write_text('dirty')
        with self.assertRaises(ValueError):c.source(self.root,self.head,self.env)
        path.unlink();(self.root/'.gitignore').write_text('hidden\n');self.git('add','.');self.git('commit','-qm','ignore')
        head=self.git('rev-parse','HEAD');(self.root/'hidden').write_text('hidden')
        with self.assertRaises(ValueError):c.source(self.root,head,self.env)
        (self.root/'hidden').unlink()
        path=self.root/next(iter(c.SOURCES));raw=path.read_text();path.unlink();link=self.root/'elsewhere';link.write_text(raw);path.symlink_to(link)
        self.git('add','.');self.git('commit','-qm','linked source')
        with self.assertRaises(ValueError):c.source(self.root,self.git('rev-parse','HEAD'),self.env)
    def test_exact_canonical_checkout_origins(self):
        original = c.source(self.root, self.head, self.env)
        for suffix in ('', '.git'):
            with self.subTest(suffix=suffix):
                self.git('remote', 'set-url', 'origin', 'https://github.com/' + c.REPOSITORY + suffix)
                self.assertEqual(c.source(self.root, self.head, self.env), original)

    def test_origin_variants_are_not_normalized_or_accepted(self):
        for value in rejected_repository_urls():
            with self.subTest(origin=value):
                self.git('remote', 'set-url', 'origin', value)
                with self.assertRaisesRegex(ValueError, '^origin$'):
                    c.source(self.root, self.head, self.env)

    def test_both_origins_preserve_head_cleanliness_and_policy_pins(self):
        name = next(iter(c.SOURCES)); path = self.root / name; original = path.read_text()
        for suffix in ('', '.git'):
            with self.subTest(suffix=suffix):
                self.git('remote', 'set-url', 'origin', 'https://github.com/' + c.REPOSITORY + suffix)
                head = self.git('rev-parse', 'HEAD')
                with self.assertRaisesRegex(ValueError, 'checkout-head-tree'):
                    c.source(self.root, 'f' * 40, self.env)
                path.write_text(original + '\n# changed policy\n')
                with self.assertRaisesRegex(ValueError, 'dirty-checkout'):
                    c.source(self.root, head, self.env)
                self.git('add', name); self.git('commit', '-qm', 'changed policy fixture')
                with self.assertRaisesRegex(ValueError, 'reviewed-source-hash'):
                    c.source(self.root, self.git('rev-parse', 'HEAD'), self.env)
                path.write_text(original)
                self.git('add', name); self.git('commit', '-qm', 'restored policy fixture')

    def test_wrong_origin(self):
        self.git('remote','set-url','origin','https://github.com/foreign/repo.git')
        with self.assertRaisesRegex(ValueError,'origin'):c.source(self.root,self.head,self.env)


class Runtime(unittest.TestCase):
    def test_scanner_exit_and_report_artifacts_fail_closed(self):
        for failure in ('scanner','missing','malformed','linked','policy','source-change','report-commit','report-root',None):
            with self.subTest(failure=failure),tempfile.TemporaryDirectory() as temp:
                out=Path(temp).resolve();root=out/'target';root.mkdir();env=env_fixture(root,out);fs,config,sarif=reports()
                identities=[dict(commit='a'*40),dict(commit='b'*40) if failure=='source-change' else dict(commit='a'*40)]
                fs['ArtifactName']=str(root);config['ArtifactName']=str(root/'infra/aws')
                if failure=='report-commit':fs['Metadata']['Commit']='f'*40
                if failure=='report-root':fs['ArtifactName']='/foreign'
                invocations=[]
                def run(argv,**kwargs):
                    invocations.append(argv)
                    destination=Path(argv[argv.index('--output')+1])
                    if failure=='policy':(out/'cache'/'policy').mkdir(exist_ok=True)
                    if failure=='linked':destination.symlink_to(out/'missing-file')
                    elif failure!='missing':
                        sarif['runs'][0]['originalUriBaseIds'] = {'ROOTPATH': {'uri': 'file://' + str(out/'filesystem.json') + '/'}}
                        destination.write_text('bad' if failure=='malformed' else c.canonical((fs,config,sarif)[len(invocations)-1]))
                    return subprocess.CompletedProcess(argv,9 if failure=='scanner' else 0)
                with patch.object(c,'context',return_value=dict(event_head='a'*40)),patch.object(c,'source',side_effect=identities),\
                     patch.object(c,'scanner',return_value=dict(version=c.VERSION)),patch.object(c.shutil,'which',return_value='/trusted/trivy'),\
                     patch.object(c.subprocess,'run',side_effect=run):
                    if failure:
                        with self.assertRaises((ValueError,FileNotFoundError)):c.execute(root,out,env)
                    else:
                        receipt=c.execute(root,out,env)
                        self.assertEqual(receipt['status'],'passed')
                        self.assertEqual(receipt['schema'],'ncdit-trivy-contract-receipt-v2')
                        self.assertEqual(len(receipt['report_sha256']),3)
                        self.assertEqual(len(receipt['scanner_exits']),3)
                        self.assertEqual(receipt['organization_policy_acceptance'],'established-for-this-contract')
                if failure=='scanner':
                    self.assertEqual(len(invocations),1)
                    self.assertEqual(c.decode((out/'scanner-exits.json').read_bytes())[0]['exit_code'],9)


class Workflow(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        import yaml
        cls.text=(ROOT/'.github/workflows/pr-security-gate.yml').read_text()
        cls.workflow=yaml.safe_load(cls.text)
        cls.steps=cls.workflow['jobs']['precheck']['steps']
        cls.byid={s.get('id'):s for s in cls.steps if s.get('id')}

    def test_legacy_action_inputs_and_raw_blocks_unchanged(self):
        # Digest of the three ORIGINAL step blocks after removing only the new
        # CyberCoach condition. This independently pins names, action SHAs,
        # inputs, output path and original always()/hashFiles() semantics.
        for name,expected in DATA['legacy_blocks'].items():
            lines=self.text.splitlines(keepends=True);start=next(i for i,l in enumerate(lines) if l.strip()=='- name: '+name)
            end=next((i for i in range(start+1,len(lines)) if lines[i].startswith('      - name:') or lines[i].startswith('      #')),len(lines))
            block=''.join(lines[start:end])
            block=block.replace("        if: github.repository != 'NC-DIT-Open-Source/CyberCoach-NC'\n",'')
            block=block.replace(" && github.repository != 'NC-DIT-Open-Source/CyberCoach-NC'",'')
            self.assertEqual(hashlib.sha256(block.encode()).hexdigest(),expected,name)

    def test_all_added_steps_are_cybercoach_only(self):
        for step in self.steps:
            if step['name'].startswith('CyberCoach'):
                self.assertIn("github.repository == '"+c.REPOSITORY+"'",step['if'])
                self.assertNotIn('continue-on-error',step)
        self.assertEqual(self.byid['trivy']['with']['scanners'],'vuln,misconfig,secret,license')
        self.assertEqual(self.byid['trivy']['with']['severity'],'CRITICAL,HIGH')
        self.assertEqual(self.byid['trivy']['with']['exit-code'],'1')

    def test_pinned_setup_and_every_action(self):
        setup=next(s for s in self.steps if s['name']=='CyberCoach pinned Trivy setup')
        self.assertEqual(setup['uses'],'aquasecurity/setup-trivy@'+c.SETUP)
        self.assertEqual(setup['with'],dict(version='v'+c.VERSION,cache=False))
        for line in self.text.splitlines():
            if 'uses:' in line:self.assertRegex(line,r'@[0-9a-f]{40} #')

    def test_embedded_source_is_isolated_and_context_is_github_owned(self):
        step=self.byid['cybercoach_trivy']
        self.assertIn("python3 -I - <<'CC_TRIVY_PY'",step['run'])
        self.assertNotIn('PYTHONPATH',step['run'])
        self.assertEqual(step['env']['CC_WORKFLOW_REF'],'DOLLAR{{ github.workflow_ref }}'.replace('DOLLAR',chr(36)))
        self.assertEqual(step['env']['CC_WORKFLOW_SHA'],'DOLLAR{{ github.workflow_sha }}'.replace('DOLLAR',chr(36)))
        self.assertEqual(step['env']['CC_HEAD_SHA'],'DOLLAR{{ github.event.pull_request.head.sha }}'.replace('DOLLAR',chr(36)))
        source=(HERE/'trivy_contract.py').read_text().strip()
        self.assertIn(source,step['run'])

    def test_gate_requires_classifier_sarif_and_artifact_for_every_outcome(self):
        gate=self.byid['cybercoach_gate']
        for field in ('CLASSIFICATION','SARIF','ARTIFACTS'):
            for status in ('failure','cancelled','skipped',''):
                env=dict(os.environ,CLASSIFICATION='success',SARIF='success',ARTIFACTS='success');env[field]=status
                result=subprocess.run(['bash','-c',gate['run']],env=env,capture_output=True)
                self.assertNotEqual(result.returncode,0,(field,status))
        result=subprocess.run(['bash','-c',gate['run']],env=dict(os.environ,CLASSIFICATION='success',SARIF='success',ARTIFACTS='success'),capture_output=True)
        self.assertEqual(result.returncode,0)
        artifacts=self.byid['cybercoach_evidence']
        self.assertIn('always()',artifacts['if']);self.assertEqual(artifacts['with']['if-no-files-found'],'error')
        self.assertEqual(artifacts['with']['retention-days'],7)
        self.assertNotIn('cache',artifacts['with']['path'])

    def test_summary_other_repositories_keep_original_selection(self):
        summary=next(s for s in self.steps if s['name']=='Precheck summary')
        for key,legacy,cybercoach in [('TRIVY','trivy','cybercoach_gate'),('TRIVY_SARIF','trivy_sarif','cybercoach_sarif')]:
            expected="DOLLAR{{ github.repository == '"+c.REPOSITORY+"' && steps."+cybercoach+".outcome || steps."+legacy+".outcome }}"
            self.assertEqual(summary['env'][key],expected.replace('DOLLAR',chr(36)))
        self.assertEqual(hashlib.sha256(summary['run'].encode()).hexdigest(),DATA['summary_script_sha256'])

    def test_nonprecheck_jobs_unchanged(self):
        for name,digest in DATA['other_jobs'].items():
            self.assertEqual(c.sha(c.canonical(self.workflow['jobs'][name]).encode()),digest,name)


